      font-weight: 700;
      text-align: center;
      margin-top: 50px;
      margin-bottom: 30px;
      color: #444;
    }

    .form-container {
      width: 450px;
      background-color: #FFF;
      margin: 20px auto;
      padding: 40px;
      box-shadow: 0 2px 10px rgba(0, 0, 0, .2);
