      margin-bottom: 20px;
    }

    label {
      display: block;
      margin: 0 0 5px 5px;
      font-size: 18px;
      font-weight: 600;
      color: #555;
    }

    input[type="text"],
    input[type="email"],
    input[type="password"] {
      width: 100%;
      padding: 10px;
      border: 1px solid #CCC;
      background-color: #F8F8F8;
      font-size: 16px;
      color: #444;
    }

    input[type="text"]:focus,
    input[type="email"]:focus,
    input[type="password"]:focus {
      border-color: #777;
    }

    .submit-btn {
      display: block;
      width: 100%;
      padding: 10px;
      background-color: #E74C3C;
      color: #FFF;
      font-size: 18px;
      font-weight: 700;
      border: none;
      border-radius: 5px;
      cursor: pointer;
    }

    .submit-btn:hover {
      background-color: #C0392B;
    }

    .terms {
      margin-top: 20px;
      font-size: 16px;
      line-height: 1.5em;
    }

    .terms label {
      display: inline-block;
      vertical-align: middle;
      margin: 0 5px 0 0;
    }

    .terms input[type="checkbox"] {
      display: inline-block;
      vertical-align: middle;
      margin-right: 5px;
    }

    @media (max-width: 767px) {
      .form-container {
        width: 100%;
        padding: 20px;
      }

      input[type="text"],
      input[type="email"],
      input[type="password"] {
        font-size: 14px;
      }

      label {
        font-size: 16px;
      }

      h1 {
        font-size: 24px;
        margin-top: 30px;
        margin-bottom: 20px;
      }

      .submit-btn {
        font-size: 16px;
      }

      .terms {
        font-size: 14px;
      }

      .terms label {
        margin-right: 10px;
      }
    }
  </style>
</head>

